import React from "react";
import Typical from "react-typical";
import "./Hero.css";
import Button from "@mui/material/Button";
import profile1 from "../../assets/profile.JPG";
import profile2 from "../../assets/profile2.JPG";
import Switch from "@mui/material/Switch";
export default function Hero() {
const [background, setBackground] = useState(profile1);
const handleDarkMode = (event) => {
    setDarkMode(!prefersDarkMode);
    setChangeBG(!changeBG);
  };
  return (
    <div className="hero-image container-fluid text-white p-5">
      <div className="mt-5 mb-5">
        <span className="text-center">
          {""}
          <h2>
            Hi, I'm <b>Candra Brata</b> 👏
          </h2>
          <Switch onChange={handleDarkMode} />
        </span>
        <br />
        <img
          src={profile1}
          alt="profile"
          className="profile-img" style={{"width":"200px", "height":"200px", "borderRadius":"50%", "margin":"auto", "display":"block", "marginTop":"20px", "marginBottom":"20px", "marginLeft":"auto", "marginRight":"auto"}}
        />
        <span className="primary-text">
          {" "}
          <h1>
            <Typical
              loop={Infinity}
              wrapper="b"
              steps={[
                "Web Developer",
                1000,
                "Laravel Dev",
                1000,
                "Code Igniter Dev",
                1000,
              ]}
            />
          </h1>
          <span className="profile-role-tagline">
            Building things that matter. And making them better.
          </span>
        </span>
        <div className="font-bold">Social media links:</div>
        <div>
          <a href="#" className="fab fa-linkedin"></a>
          <a href="#" className="fab fa-github"></a>
          <a href="#" className="fab fa-instagram"></a>
          <a href="#" className="fab fa-facebook"></a>
        </div>
        <div className="d-flex justify-content-center p-5">
          <Button variant="outlined">
            Hire me<i className="fas fa-arrow-right"></i>
          </Button>
          <Button variant="contained" color="success">
            <a
              href="cv2022_candrabrata.pdf"
              download="CV 2022_Candraditya Brata.pdf"
              style={{ "text-decoration": "none", color: "white" }}
            >
              Get my resume
            </a>
          </Button>
        </div>
      </div>
      {/* Wave */}
      <div class="custom-shape-divider-bottom-1649168459">
        <svg
          data-name="Layer 1"
          xmlns="http://www.w3.org/2000/svg"
          viewBox="0 0 1200 120"
          preserveAspectRatio="none"
        >
          <path
            d="M321.39,56.44c58-10.79,114.16-30.13,172-41.86,82.39-16.72,168.19-17.73,250.45-.39C823.78,31,906.67,72,985.66,92.83c70.05,18.48,146.53,26.09,214.34,3V0H0V27.35A600.21,600.21,0,0,0,321.39,56.44Z"
            class="shape-fill"
          ></path>
        </svg>
      </div>
    </div>
  );
}
